#!/usr/bin/env node
// Gallery infrastructure (the canonical copy lives in the prototype skill directory; this is a copy inside
// the project):
// scan each prototype directory below for *.mmd files (one diagram per file, with an optional first line
// `%% title: <title>`),
// and generate a model.mmd.js for every directory containing one (a derived file — do not edit by hand).
// After editing a .mmd, re-run: node docs/prototypes/sync-mmd.mjs
import { readdirSync, readFileSync, writeFileSync } from 'node:fs'
import { join, relative, basename, dirname, sep } from 'node:path'
import { fileURLToPath } from 'node:url'

const ROOT = dirname(fileURLToPath(import.meta.url))
const dirs = new Map()

function walk(dir) {
  for (const e of readdirSync(dir, { withFileTypes: true })) {
    if (e.name === 'vendor' || e.name.startsWith('.')) continue
    const p = join(dir, e.name)
    if (e.isDirectory()) walk(p)
    else if (e.name.endsWith('.mmd')) {
      const list = dirs.get(dir) ?? []
      list.push(p)
      dirs.set(dir, list)
    }
  }
}
walk(ROOT)

for (const [dir, files] of dirs) {
  const entries = files.sort().map((f) => {
    const src = readFileSync(f, 'utf8').trim()
    const m = src.match(/^%%\s*title:\s*(.+)$/m)
    return { title: m ? m[1].trim() : basename(f, '.mmd'), src }
  })
  const key = relative(ROOT, dir).split(sep).join('/')
  const out =
    '// Derived file: generated by sync-mmd.mjs from the *.mmd files in this directory. Do not edit by hand;\n' +
    '// change the .mmd and re-run the script instead.\n' +
    'window.MERMAID_SOURCES = window.MERMAID_SOURCES || {};\n' +
    `window.MERMAID_SOURCES[${JSON.stringify(key)}] = ${JSON.stringify(entries, null, 2)};\n`
  writeFileSync(join(dir, 'model.mmd.js'), out)
  console.log(`sync: ${key} ← ${files.map((f) => basename(f)).join(', ')}`)
}
if (!dirs.size) console.log('No .mmd files found')
